s=p.read_text(encoding='utf-8');before=s;changes=[]
def rep(old,new,count=1):
    global s
    n=s.count(old)
    assert n==count,(old[:100],n,count)
    s=s.replace(old,new);changes.append(old[:100])
def block(start,end,new):
    global s
    a=s.index(start);b=s.index(end,a)
    s=s[:a]+new+'\n\n'+s[b:];changes.append(start)
def paragraph(prefix,new):
    global s
    a=s.index(prefix);b=s.index('\n\n',a)
    s=s[:a]+new+s[b:];changes.append(prefix)
